package sk.nhl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static sk.nhl.Json.*;

class DataCollectorTest {
    static String header="team,season,gameId,gameDate,situation,iceTime,xGoalsFor,xGoalsAgainst,penaltiesFor,penaltiesAgainst,shotsOnGoalFor,shotsOnGoalAgainst,highDangerShotsFor,highDangerShotsAgainst\n";
    static String gameRows(String team,int season,String date,int number){String id=season+"02"+String.format("%04d",number);return team+","+season+","+id+","+date+",all,3600,4,3,3,5,30,25,8,7\n"+team+","+season+","+id+","+date+",5on5,2400,2,1,0,0,20,18,6,4\n"+team+","+season+","+id+","+date+",5on4,300,1,0,0,0,4,0,1,0\n"+team+","+season+","+id+","+date+",4on5,600,0,2,0,0,0,4,0,2\n";}
    static ObjectNode official(String id,String day,String time,String zone){return obj("id",id,"gameType",2,"gameDate",day,"startTimeUTC",time,"gameState","OFF","venueTimezone",zone,"homeTeam",obj("abbrev","BOS","score",3),"awayTeam",obj("abbrev","COL","score",2),"gameOutcome",obj("lastPeriodType","REG"));}
    @Test void csvSupportsPublishedExportFormat(){var rows=Csv.read("\ufeffteam,team,note\r\nBOS,BOS,\"a, b\n\"\"quoted\"\"\"\r\n");assertEquals("a, b\n\"quoted\"",rows.get(0).get("note"));assertThrows(IllegalArgumentException.class,()->Csv.read("team,team\nBOS,COL\n"));assertThrows(IllegalArgumentException.class,()->Csv.read("a,b\n1\n"));}
    @Test void bulkExportIsFilteredBeforeAllocatingFullHistory()throws Exception{String csv=header+gameRows("BOS",2026,"20261017",1)+gameRows("BOS",2025,"20251001",1)+gameRows("BOS",2024,"20241001",1)+gameRows("COL",2026,"20261017",1);Map<String,String> selected=DataCollector.selectBulk(new java.io.StringReader(csv),2026);assertEquals(Set.of("BOS","COL"),selected.keySet());assertEquals(8,Csv.read(selected.get("BOS")).size());assertEquals(4,Csv.read(selected.get("COL")).size());assertFalse(selected.get("BOS").contains("20241001"));assertThrows(IllegalArgumentException.class,()->DataCollector.selectBulk(new java.io.StringReader("unexpected,header\n"),2026));}
    @Test void ratesUseSituationIceTimeAndExcludeFutureAndWrongSeason(){String csv=header+gameRows("BOS",2026,"20261017",1)+gameRows("BOS",2026,"20261020",2)+gameRows("BOS",2025,"20251017",3);JsonNode p=DataCollector.aggregate(Csv.read(csv),"BOS",2026,LocalDate.parse("2026-10-20"));JsonNode v=p.path("values");assertEquals(1,v.path("games").asInt());assertEquals(3,v.path("xgf_5v5_per60").asDouble(),1e-12);assertEquals(12,v.path("pp_xgf_per60").asDouble(),1e-12);assertEquals(12,v.path("pk_xga_per60").asDouble(),1e-12);assertEquals(5,v.path("pp_drawn_per_game").asDouble());assertEquals(3,v.path("penalties_taken_per_game").asDouble());assertEquals(9,v.path("high_danger_for_per60").asDouble());assertEquals(1,p.path("game_ids").size());}
    @Test void missingSituationAndZeroIceTimeNeverBecomeZeroRates(){String csv=(header+gameRows("BOS",2026,"20261017",1)).replace("5on4,300","5on4,0");JsonNode p=DataCollector.aggregate(Csv.read(csv),"BOS",2026,LocalDate.parse("2026-10-20"));assertFalse(p.path("values").has("pp_xgf_per60"));List<Map<String,String>> rows=new ArrayList<>(Csv.read(csv));rows.removeIf(r->r.get("situation").equals("4on5"));assertFalse(DataCollector.aggregate(rows,"BOS",2026,LocalDate.parse("2026-10-20")).path("values").has("pk_xga_per60"));}
    @Test void pointsUseOfficialFinalGamesAndOtLoss(){ObjectNode a=official("1","2026-10-17","2026-10-17T23:00:00Z","America/New_York"),b=a.deepCopy();b.put("id","2");((ObjectNode)b.path("homeTeam")).put("score",1);((ObjectNode)b.path("gameOutcome")).put("lastPeriodType","OT");ObjectNode future=a.deepCopy();future.put("gameDate","2026-10-20");assertEquals(.75,DataCollector.points(obj("games",List.of(a,b,future)),"BOS",LocalDate.parse("2026-10-20"),Instant.parse("2026-10-20T12:00:00Z")).path("value").asDouble());assertEquals(2025,DataCollector.season(LocalDate.parse("2026-06-01")));assertEquals(2026,DataCollector.season(LocalDate.parse("2026-10-01")));}
    @Test void goalieStartsAreNotAppearancesAndGsaxUsesAllStrengths(){String csv="season,gameId,gameDate,situation,xGoals,goals,icetime\n2026,2026020001,20261017,all,3,2,3600\n2026,2026020002,20261018,all,1,1,1200\n2026,2026020003,20261020,all,99,0,3600\n";JsonNode log=obj("gameLog",List.of(obj("gameId","2026020001","gameDate","2026-10-17","gamesStarted",1),obj("gameId","2026020002","gameDate","2026-10-18","gamesStarted",0),obj("gameId","2026020003","gameDate","2026-10-20","gamesStarted",1)));JsonNode values=DataCollector.goaliePeriod(Csv.read(csv),log,2026,LocalDate.parse("2026-10-20"),"current").path("values");assertEquals(1,values.path("starts_current").asInt());assertEquals(.75,values.path("gsax_per60_current").asDouble());assertThrows(IllegalArgumentException.class,()->DataCollector.goaliePeriod(Csv.read(csv),obj(),2026,LocalDate.parse("2026-10-20"),"current"));List<Map<String,String>> partial=Csv.read(csv).subList(0,1);assertFalse(DataCollector.goaliePeriod(partial,log,2026,LocalDate.parse("2026-10-20"),"current").path("values").has("gsax_per60_current"));}
    @Test void backToBackAndArenaTimeZoneProxyAreExplicit(){ObjectNode data=template("2026-10-20","2026-10-21T00:00:00Z");ObjectNode g=(ObjectNode)data.path("games").get(0);JsonNode prior=official("previous","2026-10-19","2026-10-20T02:00:00Z","America/Los_Angeles"),current=official("123","2026-10-20","2026-10-21T00:00:00Z","America/New_York");ArrayNode paths=arr();DataCollector.addContext(g,"home",LocalDate.parse("2026-10-20"),obj("games",List.of(prior,current)),obj("id","e"),paths,arr());assertEquals(0,at(g,"home.context.rest_days").asInt());assertEquals(3,at(g,"home.context.travel_timezones").asInt());assertTrue(text(g.path("checks").path("fields").path("home.context.travel_timezones"),"note").contains("proxy"));}
    @Test void goalieSeasonSummaryNeedsExactNhlCountTimeAndCutoff(){Map<String,String> row=Map.of("season","2026","games_played","2","icetime","4800","xgoals","4","goals","3");ObjectNode log=obj("gameLog",List.of(obj("gameId","2026020001","gameDate","2026-10-17","gamesStarted",1,"toi","60:00"),obj("gameId","2026020002","gameDate","2026-10-18","gamesStarted",0,"toi","20:00")));LocalDate cutoff=LocalDate.parse("2026-10-20");assertEquals(.75,DataCollector.goalieSummary(row,log,2026,cutoff,"current").path("values").path("gsax_per60_current").asDouble());assertFalse(DataCollector.goalieSummary(row,log,2026,LocalDate.parse("2026-10-18"),"current").path("values").has("gsax_per60_current"));Map<String,String> wrong=new HashMap<>(row);wrong.put("icetime","4799");assertFalse(DataCollector.goalieSummary(wrong,log,2026,cutoff,"current").path("values").has("gsax_per60_current"));wrong.put("icetime","4800");wrong.put("games_played","3");assertFalse(DataCollector.goalieSummary(wrong,log,2026,cutoff,"current").path("values").has("gsax_per60_current"));}
    static ObjectNode template(String day,String start){return Schedule.template(obj("gameWeek",List.of(obj("date",day,"games",List.of(obj("id",123,"gameType",2,"startTimeUTC",start,"gameState","FUT","homeTeam",obj("abbrev","BOS"),"awayTeam",obj("abbrev","COL")))))),day,Instant.now().toString(),"https://api-web.nhle.com/v1/schedule/"+day);}
    @Test void failedSourcesStayUnfilledAndAreRetried(){MemoryStore store=new MemoryStore();AtomicInteger calls=new AtomicInteger();DataCollector collector=new DataCollector(store,url->{calls.incrementAndGet();throw new IllegalStateException("HTTP 503");},Clock.systemUTC());ObjectNode data=template("2099-01-01","2099-01-02T00:00:00Z");JsonNode result=collector.enrich("2099-01-01",data);assertTrue(result.path("warnings").size()>0);assertEquals(0,result.path("coverage").path("critical_found").asInt());assertEquals("not_checked",text(result.path("dataset").path("games").get(0).path("checks").path("fields").path("home.current.xgf_5v5_per60"),"status"));int first=calls.get();collector.team("2099-01-01","BOS");assertTrue(calls.get()>first);}
    @Test void existingDayIsRepairedAsynchronouslyAndNativeFieldsCannotBeErased(){MemoryStore store=new MemoryStore();List<ObjectNode>jobs=new ArrayList<>();String day="2099-01-01";Workflow original=new Workflow(store,d->template(d,"2099-01-02T00:00:00Z"),jobs::add);original.start(day);ObjectNode old=original.require(day);old.put("state","INCOMPLETE");old.put("revision",23);((ObjectNode)old.path("dataset").path("games").get(0).path("home").path("roster")).set("returns",M.valueToTree(List.of("preserve researched player")));store.put("days/"+day+".json",old);
        DataCollector collector=new DataCollector(store,url->{String content;if(url.endsWith(".csv")){String team=url.contains("BOS")?"BOS":"COL";content=header+gameRows(team,2098,"20981230",1)+gameRows(team,2097,"20971001",1);}else content=obj("games",List.of(official("prev","2098-12-30","2098-12-30T22:00:00Z","America/Denver"),official("123",day,"2099-01-02T00:00:00Z","America/New_York"))).toString();return new DataCollector.Download(content,url,Instant.now().toString());},Clock.systemUTC());Workflow w=new Workflow(store,d->{throw new AssertionError("Existing official schedule must be retained");},jobs::add,collector);
        assertEquals("PREFILLING",text(w.start(day),"state"));assertEquals(1,jobs.size());w.start(day);assertEquals(1,jobs.size());assertThrows(BusyException.class,()->w.saveGame(day,old.path("dataset").path("games").get(0),arr(),23));assertEquals("PREFILLING",text(w.finish(day,1000),"state"));w.calculate(jobs.get(0));assertEquals(24,w.read(day).path("revision").asInt());assertEquals(32,w.read(day).path("coverage").path("critical_found").asInt());assertEquals("preserve researched player",w.read(day).path("games").get(0).path("home").path("roster").path("returns").get(0).asText());ObjectNode game=w.read(day).path("games").get(0).deepCopy();((ObjectNode)game.path("home").path("current")).putNull("xgf_5v5_per60");assertThrows(IllegalArgumentException.class,()->w.saveGame(day,game,arr(),24));w.calculate(jobs.get(0));assertEquals(24,w.read(day).path("revision").asInt());assertTrue(store.keys("history/").size()>0);
    }
    @Test void closedUnavailableChecklistIsNotCompleteData(){ObjectNode data=resource("demo.json").deepCopy();for(JsonNode g:data.path("games"))for(String p:Checks.PATHS){String[] parts=p.split("\\.");ObjectNode parent=(ObjectNode)g.path(parts[0]).path(parts[1]);if(!List.of("quantified","absences").contains(parts[2]))parent.putNull(parts[2]);((ObjectNode)g.path("checks").path("fields")).set(p,obj("status","unavailable","evidence_ids",List.of("demo"),"note","source unavailable"));}JsonNode coverage=Checks.coverage(data);assertEquals(0,coverage.path("field_found").asInt());assertEquals(0,coverage.path("critical_ready_games").asInt());assertEquals(coverage.path("checklist_total").asInt(),coverage.path("checklist_closed").asInt());}
}
